import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import 'audio_players_service.dart';

/// The game's sound effects. Each is a WAV file in assets/sounds named after
/// the value, generated by tool/generate_sounds.dart.
enum SoundEffect { place, win, lose, draw }

/// Plays sound effects. Whether sound is switched on is the controller's
/// business, not this service's.
abstract class AudioService {
  /// Loads every effect so the first one plays without a delay. Safe to call
  /// more than once.
  Future<void> preload();

  void play(SoundEffect effect);

  Future<void> dispose();
}

/// Triggers the device's haptics.
abstract class HapticsService {
  /// A light tick, for placing a mark.
  void selectionClick();

  /// A firmer bump, for the end of a round.
  void mediumImpact();
}

class SystemHapticsService implements HapticsService {
  const SystemHapticsService();

  @override
  void selectionClick() => HapticFeedback.selectionClick();

  @override
  void mediumImpact() => HapticFeedback.mediumImpact();
}

/// Tests override this with a fake.
final audioServiceProvider = Provider<AudioService>((ref) {
  final service = AudioPlayersAudioService();
  ref.onDispose(service.dispose);
  return service;
});

/// Tests override this with a fake.
final hapticsServiceProvider = Provider<HapticsService>(
  (ref) => const SystemHapticsService(),
);
